import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        // Pack the key (number of set bits, value) into one long so a plain sort orders by it.
        long[] keys = new long[n];
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            keys[i] = ((long) Long.bitCount(v) << 32) | v;
        }
        Arrays.sort(keys);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(keys[i] & 0xFFFFFFFFL);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math/bits"
	"os"
	"sort"
	"strconv"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	a := make([]uint, n)
	for i := range a {
		fmt.Fscan(in, &a[i])
	}
	// Key: (number of set bits, value).
	sort.Slice(a, func(i, j int) bool {
		pi, pj := bits.OnesCount(a[i]), bits.OnesCount(a[j])
		if pi != pj {
			return pi < pj
		}
		return a[i] < a[j]
	})
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i, v := range a {
		if i > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.FormatUint(uint64(v), 10))
	}
	w.WriteByte('\n')
}
